writing.exampleCode:
fn main() {
    let before = vec![1u8, 2, 3];
    let allocation = before.as_ptr();
    let after = before;
    assert_eq!(after.as_ptr(), allocation);
    assert_eq!(after, [1, 2, 3]);
}

writing.practiceCode:
fn main() {
    let a = vec![7u8; 1024];
    let pointer = a.as_ptr();
    let b = a;
    assert_eq!(b.as_ptr(), pointer);
    assert_eq!(b.len(), 1024);
}
